1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireUser } from "./auth";
6	
7	/** Average calendar month in ms (365.25/12 ≈ 30.44d) for duration-based proration. */
8	const MS_PER_AVG_MONTH = 30.44 * 86400_000;
9	
10	/**
11	 * Server lifecycle "extras" — scheduled backups, reinstall-to-a-different-OS and
12	 * resize-down. These complement the primary flows in `lib/actions-server.ts`
13	 * (create backup, resize-up, reinstall-same-OS). Every op is ownership-checked
14	 * and respects the "one in-flight job per server" invariant.
15	 */
16	
17	/** Allowed scheduled-backup cadences (hours). Kept small + human-friendly. */
18	export const BACKUP_INTERVAL_CHOICES = [12, 24, 48, 72, 168] as const;
19	
20	async function ownedServer(serverId: string) {
21	  const user = await requireUser();
22	  const server = await db.server.findUnique({
23	    where: { id: serverId },
24	    include: { plan: true, osTemplate: true },
25	  });
26	  if (!server) throw new Error("Not found");
27	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
28	  return { user, server };
29	}
30	
31	async function hasInflightJob(serverId: string): Promise<boolean> {
32	  const pending = await db.job.count({
33	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
34	  });
35	  return pending > 0;
36	}
37	
38	// ---------- 1. Scheduled backups ----------
39	
40	/**
41	 * Enable/disable recurring backups and set the cadence. When enabling we do NOT
42	 * touch `lastAutoBackup` — a null/stale value simply lets the sweep run the
43	 * first backup on its next pass.
44	 */
45	export async function setBackupSchedule(
46	  serverId: string,
47	  enabled: boolean,
48	  intervalHours: number
49	): Promise<{ error?: string }> {
50	  const { user, server } = await ownedServer(serverId);
51	
52	  if (enabled && !BACKUP_INTERVAL_CHOICES.includes(intervalHours as any)) {
53	    return { error: "Choose a valid backup interval." };
54	  }
55	
56	  await db.server.update({
57	    where: { id: server.id },
58	    data: {
59	      autoBackup: enabled,
60	      backupIntervalHours: enabled ? intervalHours : null,
61	    },
62	  });
63	  await db.auditLog.create({
64	    data: {
65	      userId: user.id,
66	      action: "server.backup_schedule",
67	      detail: enabled ? `${serverId} every ${intervalHours}h` : `${serverId} disabled`,
68	    },
69	  });
70	  revalidatePath(`/dashboard/servers/${serverId}`);
71	  return {};
72	}
73	
74	// ---------- 2. Reinstall to a different OS ----------
75	
76	/**
77	 * Switch the server to a different OS image and reinstall. This ERASES all data:
78	 * the worker's REINSTALL handler destroys the VM and re-provisions it from
79	 * `Server.osTemplateId`, so we persist the new template BEFORE enqueuing.
80	 */
81	export async function reinstallToOs(
82	  serverId: string,
83	  osTemplateId: string
84	): Promise<{ error?: string }> {
85	  const { user, server } = await ownedServer(serverId);
86	
87	  if (!["RUNNING", "STOPPED"].includes(server.status)) {
88	    return { error: "Server must be running or stopped to reinstall." };
89	  }
90	
91	  const os = await db.osTemplate.findUnique({ where: { id: osTemplateId } });
92	  if (!os?.active) return { error: "That operating system isn't available." };
93	  if (os.id === server.osTemplateId) {
94	    return { error: "This server is already running that operating system." };
95	  }
96	  if (server.plan.ramMB < os.minRamMB) {
97	    return { error: `${os.name} needs at least ${os.minRamMB / 1024} GB RAM — your plan has ${server.plan.ramMB / 1024} GB.` };
98	  }
99	  if (server.plan.diskGB < os.minDiskGB) {
100	    return { error: `${os.name} needs at least ${os.minDiskGB} GB disk — your plan has ${server.plan.diskGB} GB.` };
101	  }
102	
103	  if (await hasInflightJob(serverId)) {
104	    return { error: "Another operation is already in progress on this server." };
105	  }
106	
107	  // A reinstall destroys and re-clones the VM (same vmid). Its disks — including
108	  // any block-storage volume disk (vm-<vmid>-disk-N) — are purged with it. A
109	  // *detached* volume still keeps its disk under this vmid (Proxmox "unused"), so
110	  // purge wipes it too. Refuse while ANY volume is pinned to this server so the
111	  // customer must delete it (which cleanly destroys just that disk) first.
112	  const pinnedVolumes = await db.volume.count({ where: { serverId } });
113	  if (pinnedVolumes > 0) {
114	    return {
115	      error: `Delete the ${pinnedVolumes} block-storage volume${pinnedVolumes === 1 ? "" : "s"} on this server before reinstalling — a reinstall wipes the whole disk, and volume data can't be recovered.`,
116	    };
117	  }
118	
119	  // Persist the target OS first so the REINSTALL handler (which re-provisions
120	  // from Server.osTemplateId) rebuilds onto the new image, then enqueue.
121	  await db.server.update({ where: { id: server.id }, data: { osTemplateId: os.id } });
122	  await db.job.create({ data: { type: "REINSTALL", serverId } });
123	  await db.auditLog.create({
124	    data: {
125	      userId: user.id,
126	      action: "server.reinstall_os",
127	      detail: `${serverId} -> ${os.slug} (was ${server.osTemplate.slug})`,
128	    },
129	  });
130	  revalidatePath(`/dashboard/servers/${serverId}`);
131	  return {};
132	}
133	
134	// ---------- 3. Resize-down ----------
135	
136	/**
137	 * Move a server to a SMALLER (cheaper) plan. CPU/RAM can shrink freely, but the
138	 * disk can NOT shrink on the hypervisor, so we require the target plan's disk to
139	 * be >= the current plan's disk (the worker's RESIZE handler hard-fails a shrink
140	 * otherwise). A prorated credit for the price difference over the remaining term
141	 * is returned to the wallet.
142	 */
143	export async function resizeServerDown(
144	  serverId: string,
145	  newPlanId: string
146	): Promise<{ error?: string }> {
147	  const { user, server } = await ownedServer(serverId);
148	
149	  const newPlan = await db.plan.findUnique({ where: { id: newPlanId } });
150	  if (!newPlan?.active) return { error: "Plan not available." };
151	  if (newPlan.id === server.planId) return { error: "Server is already on this plan." };
152	  if (!["RUNNING", "STOPPED"].includes(server.status)) return { error: "Server is busy." };
153	
154	  // This action is downgrades only — upgrades go through resizeServer().
155	  if (newPlan.priceCents >= server.plan.priceCents) {
156	    return { error: "This is not a smaller plan — use the upgrade flow instead." };
157	  }
158	  // Disk can't shrink destructively; block the move rather than lose data.
159	  if (newPlan.diskGB < server.plan.diskGB) {
160	    return {
161	      error: `Disk can't shrink — ${newPlan.name} has a ${newPlan.diskGB} GB disk but your server uses ${server.plan.diskGB} GB. Pick a smaller plan whose disk is at least ${server.plan.diskGB} GB.`,
162	    };
163	  }
164	
165	  if (await hasInflightJob(serverId)) {
166	    return { error: "Another operation is already in progress on this server." };
167	  }
168	
169	  // Prorated credit over the ACTUAL remaining duration, not a fraction of a single
170	  // term. `renewNow` can stack expiresAt many terms into the future, so the old
171	  // "fraction of one term" clamp under-credited (or over-credited) prepaid users.
172	  // Credit the monthly price difference for every remaining month. Null expiresAt
173	  // (free/admin servers) => 0.
174	  let creditCents = 0;
175	  if (!server.isFree && server.expiresAt) {
176	    const now = Date.now();
177	    const remainingMonths = Math.max(0, (server.expiresAt.getTime() - now) / MS_PER_AVG_MONTH);
178	    const monthlyDelta = server.plan.priceCents - newPlan.priceCents; // positive: old monthly > new monthly
179	    creditCents = Math.max(0, Math.round(monthlyDelta * remainingMonths));
180	  }
181	
182	  await db.$transaction([
183	    ...(creditCents > 0
184	      ? [
185	          db.user.update({
186	            where: { id: server.userId },
187	            data: { balanceCents: { increment: creditCents } },
188	          }),
189	          db.walletTransaction.create({
190	            data: {
191	              userId: server.userId,
192	              amountCents: creditCents,
193	              description: `Downgrade to ${newPlan.name} (prorated credit) — ${server.hostname}`,
194	            },
195	          }),
196	        ]
197	      : []),
198	    // Record the amount credited on the job so the worker's RESIZE handler can
199	    // REVERSE it (re-debit `payload.prorateCents` from the wallet) if the resize
200	    // terminally fails — the credit is committed here, before the job runs.
201	    // INTEGRATION NEEDED: worker must honour payload.prorateCents/direction.
202	    db.job.create({
203	      data: {
204	        type: "RESIZE",
205	        serverId,
206	        payload: { planId: newPlan.id, prorateCents: creditCents, direction: "down" } as any,
207	      },
208	    }),
209	    db.auditLog.create({
210	      data: {
211	        userId: user.id,
212	        action: "server.resize_down",
213	        detail: `${serverId} -> ${newPlan.slug} credit=${creditCents}`,
214	      },
215	    }),
216	  ]);
217	
218	  revalidatePath(`/dashboard/servers/${serverId}`);
219	  return {};
220	}
221

1	import { db } from "../lib/db";
2	import { pve, node as envNode, waitForTask, nextVmid, pveFor, vmStatus } from "../lib/proxmox";
3	import { SANDBOX } from "../lib/sandbox";
4	import type { Job } from "@prisma/client";
5	
6	/**
7	 * Block storage volume handlers (add-on disks attached to a VPS).
8	 *
9	 * `worker/index.ts` owns the job loop and the `handlers` map; wire these in there:
10	 *   VOLUME_CREATE: volumeCreate,
11	 *   VOLUME_ATTACH: volumeAttach,
12	 *   VOLUME_DETACH: volumeDetach,
13	 *   VOLUME_DELETE: volumeDelete,
14	 *
15	 * Ownership + validation are enforced at enqueue time (lib/actions-volumes.ts),
16	 * so these handlers trust `payload.volumeId`.
17	 *
18	 * A volume's underlying Proxmox disk only exists once it has been attached at
19	 * least once. `Volume.diskName` stores the STABLE Proxmox volume id of that disk
20	 * (e.g. "vmdata:vm-101-disk-1") — not a slot — because the slot/unused index
21	 * changes across detach/re-attach; we always re-scan the VM config to find the
22	 * disk's current key (scsiN while attached, unusedN while detached).
23	 */
24	
25	async function loadVolume(job: Job) {
26	  const payload = (job.payload ?? {}) as { volumeId?: string };
27	  if (!payload.volumeId) throw new Error("volume job: missing volumeId");
28	  const volume = await db.volume.findUnique({
29	    where: { id: payload.volumeId },
30	    include: { server: { include: { node: true } } },
31	  });
32	  if (!volume) throw new Error(`Volume ${payload.volumeId} not found`);
33	  return volume;
34	}
35	
36	/** Resolve the Proxmox client + node row for a server (mirrors worker/index.ts). */
37	async function nodeFor(server: any) {
38	  const n =
39	    server?.node ??
40	    (await db.node.findFirst({ where: { isPrimary: true } })) ??
41	    (await db.node.findFirst({ where: { enabled: true } }));
42	  if (!n) {
43	    return {
44	      conn: {
45	        get: pve.get,
46	        post: pve.post,
47	        put: pve.put,
48	        del: pve.del,
49	        node: envNode,
50	        waitForTask,
51	        nextVmid,
52	        vmStatus,
53	      } as any,
54	      row: null,
55	    };
56	  }
57	  return {
58	    conn: pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret }),
59	    row: n,
60	  };
61	}
62	
63	async function notify(userId: string, title: string, body?: string, href?: string) {
64	  try {
65	    await db.notification.create({ data: { userId, title, body, href } });
66	  } catch (e) {
67	    console.error("[volumes] notify failed", e);
68	  }
69	}
70	
71	/** Strip Proxmox disk options: "vmdata:vm-101-disk-1,size=10G" -> "vmdata:vm-101-disk-1". */
72	function volidOf(configValue: unknown): string {
73	  return String(configValue ?? "").split(",")[0].trim();
74	}
75	
76	/** First free scsiN slot (scsi0 is the OS disk). Proxmox supports scsi0..scsi30. */
77	function freeScsiSlot(config: Record<string, any>): string {
78	  for (let i = 1; i <= 30; i++) {
79	    if (config[`scsi${i}`] === undefined) return `scsi${i}`;
80	  }
81	  throw new Error("no free scsi slot available on this VM");
82	}
83	
84	/** Find the config key (scsiN / unusedN / …) that currently references `volid`. */
85	function keyForVolid(config: Record<string, any>, volid: string): string | null {
86	  for (const [k, v] of Object.entries(config)) {
87	    if (typeof v === "string" && volidOf(v) === volid) return k;
88	  }
89	  return null;
90	}
91	
92	/**
93	 * VOLUME_CREATE — logical registration only. No physical disk is created until
94	 * the volume is first attached (a Proxmox disk must live on a VM). Flip the row
95	 * from PENDING to DETACHED so the customer can attach it.
96	 */
97	export async function volumeCreate(job: Job): Promise<void> {
98	  const volume = await loadVolume(job);
99	  if (volume.status === "PENDING") {
100	    await db.volume.update({ where: { id: volume.id }, data: { status: "DETACHED" } });
101	  }
102	  await notify(
103	    volume.userId,
104	    `Volume "${volume.name}" is ready`,
105	    `${volume.sizeGB} GB block storage is available to attach to a server.`,
106	    "/dashboard/volumes"
107	  );
108	}
109	
110	/**
111	 * VOLUME_ATTACH — attach the disk to the target server's VM at a free scsi slot.
112	 * Creates the underlying disk on first attach ("<storage>:<sizeGB>"); on a
113	 * re-attach it re-uses the existing volume id so data is preserved.
114	 */
115	export async function volumeAttach(job: Job): Promise<void> {
116	  const volume = await loadVolume(job);
117	  const server = volume.server;
118	  if (SANDBOX) {
119	    // Simulate the attach with a synthetic disk id — no Proxmox config read/write.
120	    await db.volume.update({
121	      where: { id: volume.id },
122	      data: { status: "ATTACHED", serverId: server?.id ?? null, diskName: `sandbox:vol-${volume.id}` },
123	    });
124	    await notify(
125	      volume.userId,
126	      `Volume "${volume.name}" attached${server ? ` to ${server.hostname}` : ""}`,
127	      `${volume.sizeGB} GB is now available (sandbox). Format and mount it inside the server to use it.`,
128	      server ? `/dashboard/servers/${server.id}` : "/dashboard/volumes"
129	    );
130	    return;
131	  }
132	  if (!server || !server.vmid) throw new Error("volume attach: server has no VM");
133	
134	  const { conn, row } = await nodeFor(server);
135	  const storage = row?.storageNvme ?? "vmdata";
136	
137	  const config = (await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`)) as Record<string, any>;
138	  const slot = freeScsiSlot(config);
139	
140	  // Re-use the existing disk (by volid) if this volume was attached before;
141	  // otherwise let Proxmox create a fresh <storage>:<sizeGB> disk.
142	  const source = volume.diskName ? volume.diskName : `${storage}:${volume.sizeGB}`;
143	  await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { [slot]: source });
144	
145	  // Read back the real volume id Proxmox assigned/kept at the slot.
146	  const after = (await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`)) as Record<string, any>;
147	  const volid = volidOf(after[slot]) || volume.diskName || null;
148	
149	  await db.volume.update({
150	    where: { id: volume.id },
151	    data: { status: "ATTACHED", serverId: server.id, diskName: volid },
152	  });
153	  await notify(
154	    volume.userId,
155	    `Volume "${volume.name}" attached to ${server.hostname}`,
156	    `${volume.sizeGB} GB is now available as ${slot}. Format and mount it inside the server to use it.`,
157	    `/dashboard/servers/${server.id}`
158	  );
159	}
160	
161	/**
162	 * VOLUME_DETACH — detach the disk from the VM (Proxmox moves it to an "unused"
163	 * entry, preserving the data). The volume stays pinned to this server so it can
164	 * be re-attached here later.
165	 */
166	export async function volumeDetach(job: Job): Promise<void> {
167	  const volume = await loadVolume(job);
168	  const server = volume.server;
169	
170	  if (SANDBOX) {
171	    await db.volume.update({ where: { id: volume.id }, data: { status: "DETACHED" } });
172	    if (server) {
173	      await notify(
174	        volume.userId,
175	        `Volume "${volume.name}" detached from ${server.hostname}`,
176	        "The volume and its data are preserved and can be re-attached (sandbox).",
177	        "/dashboard/volumes"
178	      );
179	    }
180	    return;
181	  }
182	
183	  if (server?.vmid && volume.diskName) {
184	    const { conn } = await nodeFor(server);
185	    const config = (await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`)) as Record<string, any>;
186	    const key = keyForVolid(config, volume.diskName);
187	    if (key && key.startsWith("scsi")) {
188	      await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { delete: key });
189	    }
190	  }
191	
192	  await db.volume.update({ where: { id: volume.id }, data: { status: "DETACHED" } });
193	  if (server) {
194	    await notify(
195	      volume.userId,
196	      `Volume "${volume.name}" detached from ${server.hostname}`,
197	      "The volume and its data are preserved and can be re-attached to the same server.",
198	      "/dashboard/volumes"
199	    );
200	  }
201	}
202	
203	/**
204	 * VOLUME_DELETE — detach (if attached) then permanently destroy the underlying
205	 * disk, and remove the Volume row.
206	 */
207	export async function volumeDelete(job: Job): Promise<void> {
208	  const volume = await loadVolume(job);
209	  const server = volume.server;
210	
