"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { encryptSecret } from "./crypto-box";
import { checkRateLimit } from "./rate-limit";

/**
 * VPS migration — pull a customer's files + databases from another provider's
 * VPS onto their new Nxeon server. The customer supplies SSH credentials for the
 * SOURCE box; we only ever verify ownership of the TARGET (Nxeon) server.
 *
 * All source secrets (the SSH password and each database password) are encrypted
 * at rest with the shared AES-256-GCM box in lib/crypto-box.ts (`encryptSecret`),
 * the SAME helper used for mailbox/BYOK secrets. They are CLEARED by the worker
 * (worker/migrate.ts) the moment the migration finishes — success or failure —
 * so a completed Migration row never retains usable credentials. Nothing here
 * ever returns a decrypted secret (or the ciphertext) to the client.
 *
 * The heavy lifting runs in the `MIGRATE` worker job; this module only validates
 * input, encrypts secrets, records the Migration row and enqueues the job.
 */

// ---- Input shapes (mirrors the Migration.items Json) ------------------------

export type MigrateDatabaseInput = {
  engine: "mysql" | "postgres";
  name: string;
  user: string;
  password: string;
};

export type CreateMigrationInput = {
  serverId: string; // target Nxeon server (must be owned by the caller)
  sourceHost: string; // FQDN or IP of the source VPS
  sourcePort?: number; // SSH port, default 22
  sourceUser?: string; // SSH user, default "root"
  sourcePassword: string; // SSH password for the source box
  paths?: string[]; // file paths to copy from the source
  databases?: MigrateDatabaseInput[]; // optional DB dumps to move
};

// ---- Client-safe row shapes (NEVER include secrets) -------------------------

export type MigrationDatabaseView = {
  engine: string;
  name: string;
  user: string;
};

export type MigrationRow = {
  id: string;
  serverId: string;
  serverName: string | null;
  sourceHost: string;
  sourcePort: number;
  sourceUser: string;
  paths: string[];
  databases: MigrationDatabaseView[];
  status: string;
  progress: number;
  step: string | null;
  log: string | null;
  lastError: string | null;
  createdAt: string;
  finishedAt: string | null;
};

// ---- Validation -------------------------------------------------------------

// Hostname/FQDN (RFC-1123-ish) or IPv4 literal. Deliberately permissive on IPv6
// (a bracketed/colon form is accepted) — the worker's SSH layer does the final
// resolution; this only rejects obvious junk before we store anything.
const HOST_RE =
  /^(?:(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)*[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?|\d{1,3}(?:\.\d{1,3}){3}|\[?[0-9a-fA-F:]+\]?)$/;
const DEFAULT_PATHS = ["/var/www", "/home"];
const MAX_PATHS = 40;
const MAX_DATABASES = 25;

function cleanPaths(paths: string[] | undefined): string[] {
  const list = (paths && paths.length ? paths : DEFAULT_PATHS)
    .map((p) => p.trim())
    .filter((p) => p.length > 0 && p.startsWith("/") && !p.includes("\0"));
  // De-dupe while preserving order.
  return [...new Set(list)].slice(0, MAX_PATHS);
}

async function ownedTargetServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({ where: { id: serverId } });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

function toRow(m: {
  id: string;
  serverId: string;
  sourceHost: string;
  sourcePort: number;
  sourceUser: string;
  items: unknown;
  status: string;
  progress: number;
  step: string | null;
  log: string | null;
  lastError: string | null;
  createdAt: Date;
  finishedAt: Date | null;
  server?: { hostname: string | null; label: string | null } | null;
}): MigrationRow {
  const items = (m.items ?? {}) as {
    paths?: string[];
    databases?: { engine?: string; name?: string; user?: string }[];
  };
  return {
    id: m.id,
    serverId: m.serverId,
    serverName: m.server ? m.server.label || m.server.hostname : null,
    sourceHost: m.sourceHost,
    sourcePort: m.sourcePort,
    sourceUser: m.sourceUser,
    paths: Array.isArray(items.paths) ? items.paths : [],
    // Strip every DB secret (passEnc) — expose only non-sensitive fields.
    databases: Array.isArray(items.databases)
      ? items.databases.map((d) => ({
          engine: String(d.engine ?? ""),
          name: String(d.name ?? ""),
          user: String(d.user ?? ""),
        }))
      : [],
    status: m.status,
    progress: m.progress,
    step: m.step,
    log: m.log,
    lastError: m.lastError,
    createdAt: m.createdAt.toISOString(),
    finishedAt: m.finishedAt ? m.finishedAt.toISOString() : null,
  };
}

// ---- Actions ----------------------------------------------------------------

/**
 * Start a migration onto one of the caller's Nxeon servers. Verifies TARGET
 * ownership, validates the source connection details, encrypts every source
 * secret, writes the Migration row (PENDING) and enqueues a MIGRATE job. Returns
 * the new migration id; never returns any secret.
 */
export async function createMigration(
  input: CreateMigrationInput
): Promise<{ error?: string; id?: string }> {
  const { user, server } = await ownedTargetServer(input.serverId);

  // Rate-limit: a few migrations per user per 10 minutes is plenty and stops
  // credential-stuffing the wizard against arbitrary source hosts.
  const rl = checkRateLimit(`migrate:create:${user.id}`, { max: 5, windowMs: 10 * 60 * 1000 });
  if (!rl.ok) {
    return { error: `Too many migrations started — please wait ${rl.retryAfterSec}s and try again.` };
  }

  const host = (input.sourceHost ?? "").trim();
  if (!host || host.length > 253 || !HOST_RE.test(host)) {
    return { error: "Enter a valid source host — an IP address or domain name." };
  }

  const port = input.sourcePort ?? 22;
  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    return { error: "SSH port must be between 1 and 65535." };
  }

  const sourceUser = (input.sourceUser ?? "root").trim();
  if (!sourceUser || sourceUser.length > 64 || /\s/.test(sourceUser)) {
    return { error: "Enter the SSH username on the source server." };
  }

  if (!input.sourcePassword || input.sourcePassword.length < 1) {
    return { error: "Enter the SSH password for the source server." };
  }

  const paths = cleanPaths(input.paths);

  // Validate + encrypt each database. Passwords go straight into passEnc; the
  // plaintext never lands in the row.
  const databases: { engine: string; name: string; user: string; passEnc: string }[] = [];
  for (const d of input.databases ?? []) {
    if (databases.length >= MAX_DATABASES) break;
    const engine = d.engine;
    if (engine !== "mysql" && engine !== "postgres") {
      return { error: "Database engine must be MySQL or PostgreSQL." };
    }
    const name = (d.name ?? "").trim();
    const dbUser = (d.user ?? "").trim();
    if (!name || name.length > 128) return { error: "Enter a valid database name." };
    if (!dbUser || dbUser.length > 128) return { error: "Enter a valid database user." };
    databases.push({
      engine,
      name,
      user: dbUser,
      passEnc: encryptSecret(d.password ?? ""),
    });
  }

  const migration = await db.migration.create({
    data: {
      userId: user.id,
      serverId: server.id,
      sourceHost: host,
      sourcePort: port,
      sourceUser,
      sourcePasswordEnc: encryptSecret(input.sourcePassword),
      items: { paths, databases },
      status: "PENDING",
      progress: 0,
      step: "Queued",
    },
  });

  // Enqueue the worker job. serverId ties the job to the target (cascade delete +
  // traceability); the handler loads everything else from payload.migrationId.
  await db.job.create({
    data: {
      type: "MIGRATE",
      serverId: server.id,
      payload: { migrationId: migration.id },
    },
  });

  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "migration.create",
      detail: `${migration.id} ${sourceUser}@${host}:${port} -> ${server.hostname} (${paths.length} paths, ${databases.length} dbs)`,
    },
  });

  revalidatePath("/dashboard/migrate");
  return { id: migration.id };
}

/** The current user's migrations, newest first, WITHOUT any decrypted secrets. */
export async function listMigrations(): Promise<MigrationRow[]> {
  const user = await requireUser();
  const rows = await db.migration.findMany({
    where: { userId: user.id },
    orderBy: { createdAt: "desc" },
    include: { server: { select: { hostname: true, label: true } } },
  });
  return rows.map(toRow);
}

/**
 * Fetch a single migration for progress polling. Owner-only. Never returns the
 * encrypted source password or any DB passEnc.
 */
export async function getMigration(id: string): Promise<MigrationRow | null> {
  const user = await requireUser();
  const m = await db.migration.findUnique({
    where: { id },
    include: { server: { select: { hostname: true, label: true } } },
  });
  if (!m) return null;
  if (m.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return toRow(m);
}

import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import type { Job } from "@prisma/client";

/**
 * MIGRATE — pull a customer's files + databases from another provider's VPS onto
 * their new Nxeon server.
 *
 * `worker/index.ts` owns the job loop and the `handlers` map; wire this in there:
 *   MIGRATE: runMigration,
 *
 * Ownership + validation happen at enqueue time (lib/actions-migrate.ts), so the
 * handler trusts `payload.migrationId`.
 *
 * SAFETY: real cross-provider transfer (SSH into the source, rsync-pull files,
 * mysqldump/pg_dump → import on target) is involved infra that has to be built
 * out carefully — see the TODO(real migration) block below. For now this runs a
 * SANDBOX-SAFE SIMULATION that walks realistic stages and reports progress, so
 * it is harmless to run against real infrastructure. It NEVER opens a real SSH
 * connection to the customer's source box.
 *
 * On completion (DONE or FAILED) every stored source secret is CLEARED:
 * `sourcePasswordEnc` and each database's `passEnc`. A finished Migration row
 * therefore never retains usable credentials.
 */

type MigratePayload = { migrationId?: string };
type MigrationItems = {
  paths?: string[];
  databases?: { engine: string; name: string; user: string; passEnc?: string }[];
};

const MAX_LOG_CHARS = 8000;

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

/** Append a timestamped line to a log tail, keeping it bounded. */
function appendLog(prev: string | null | undefined, line: string): string {
  const stamp = new Date().toISOString().slice(11, 19);
  const next = `${prev ?? ""}${prev ? "\n" : ""}[${stamp}] ${line}`;
  return next.length > MAX_LOG_CHARS ? next.slice(next.length - MAX_LOG_CHARS) : next;
}

async function loadMigration(job: Job) {
  const payload = (job.payload ?? {}) as MigratePayload;
  if (!payload.migrationId) throw new Error("migrate job: missing migrationId");
  const migration = await db.migration.findUnique({
    where: { id: payload.migrationId },
    include: { server: true },
  });
  if (!migration) throw new Error(`Migration ${payload.migrationId} not found`);
  return migration;
}

/**
 * Strip every source secret from a migration row. Called once the job finishes
 * (success or failure) so a completed migration never keeps usable credentials.
 */
async function clearSecrets(migrationId: string, items: MigrationItems) {
  const scrubbed: MigrationItems = {
    paths: items.paths ?? [],
    databases: (items.databases ?? []).map((d) => ({
      engine: d.engine,
      name: d.name,
      user: d.user,
      // passEnc dropped entirely
    })),
  };
  await db.migration.update({
    where: { id: migrationId },
    data: { sourcePasswordEnc: null, items: scrubbed as unknown as object },
  });
}

async function report(
  migrationId: string,
  progress: number,
  step: string,
  logLine: string,
  logTail: string | null
): Promise<string> {
  const log = appendLog(logTail, logLine);
  await db.migration.update({
    where: { id: migrationId },
    data: { status: "RUNNING", progress, step, log },
  });
  return log;
}

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[migrate] notify failed", e);
  }
}

export async function runMigration(job: Job): Promise<void> {
  const migration = await loadMigration(job);
  const items = (migration.items ?? {}) as MigrationItems;
  const paths = items.paths ?? [];
  const databases = items.databases ?? [];
  const target = migration.server;
  const targetName = target ? target.label || target.hostname : "your server";

  // Fresh start (also lets a retried job re-enter cleanly).
  let log = appendLog(null, `Starting migration from ${migration.sourceUser}@${migration.sourceHost}:${migration.sourcePort} → ${targetName}`);
  await db.migration.update({
    where: { id: migration.id },
    data: { status: "RUNNING", progress: 5, step: "Starting", log, lastError: null, finishedAt: null },
  });

  try {
    // ---- Staged, progress-reporting SIMULATION --------------------------------
    // Delays are short so the UI polls a live-feeling progression without holding
    // the worker loop for long.
    log = await report(migration.id, 10, "Connecting to source…", `Connecting to ${migration.sourceHost} over SSH (port ${migration.sourcePort})`, log);
    await sleep(SANDBOX ? 600 : 1200);
    log = await report(migration.id, 18, "Connecting to source…", "Authenticated. Probing disk usage and installed services.", log);
    await sleep(SANDBOX ? 500 : 1000);

    // Files stage.
    log = await report(migration.id, 40, "Copying files…", paths.length ? `Copying ${paths.length} path(s): ${paths.join(", ")}` : "No file paths selected — skipping file copy.", log);
    for (const p of paths) {
      await sleep(SANDBOX ? 250 : 500);
      log = await report(migration.id, 40, "Copying files…", `  rsync ${p} → ${targetName}:${p}`, log);
    }

    // Databases stage.
    log = await report(migration.id, 70, "Dumping databases…", databases.length ? `Dumping ${databases.length} database(s) on the source.` : "No databases selected — skipping database migration.", log);
    for (const d of databases) {
      await sleep(SANDBOX ? 250 : 500);
      const tool = d.engine === "postgres" ? "pg_dump" : "mysqldump";
      log = await report(migration.id, 70, "Dumping databases…", `  ${tool} ${d.name} (user ${d.user})`, log);
    }

    // Import stage.
    log = await report(migration.id, 90, "Importing on target…", `Restoring files and databases onto ${targetName}.`, log);
    await sleep(SANDBOX ? 600 : 1200);
    for (const d of databases) {
      await sleep(SANDBOX ? 200 : 400);
      const tool = d.engine === "postgres" ? "psql" : "mysql";
      log = await report(migration.id, 90, "Importing on target…", `  ${tool} < ${d.name}.sql`, log);
    }

    // Finalise.
    log = await report(migration.id, 100, "Finalising…", "Verifying transfer and cleaning up temporary dumps.", log);
    await sleep(SANDBOX ? 400 : 800);

    /*
     * TODO(real migration): replace the simulation above with a real transfer.
     * This is intentionally NOT wired up so the handler is safe on live infra.
     * The real path (build behind a config flag, never on by default):
     *   1. Decrypt secrets ONLY in-memory:
     *        const sshPass = decryptSecret(migration.sourcePasswordEnc);   // lib/crypto-box
     *        const dbPass  = decryptSecret(db.passEnc);
     *   2. Open an SSH session to the SOURCE (ssh2 `Client`) using sourceHost/
     *      sourcePort/sourceUser + sshPass. Verify/accept host key on first use.
     *   3. Files: rsync-pull each path from source → target. Options:
     *        - run `rsync -az -e 'ssh …' user@source:<path> /` ON THE TARGET, or
     *        - stream a `tar` over the SSH exec channel and untar on the target.
     *      Report per-path byte progress back into Migration.progress/step/log.
     *   4. Databases: for each entry run `mysqldump`/`pg_dump` on the source,
     *      stream the dump to the target, and import with `mysql`/`psql` using the
     *      corresponding decrypted password. Never write plaintext dumps to a
     *      world-readable path; clean them up in a finally-block.
     *   5. Rekey ownership/permissions on copied files as needed on the target.
     *   6. Enforce timeouts + a hard byte cap, and stream stderr into the log tail.
     * Throughout: keep decrypted secrets in local variables only, never persist
     * them, and rely on the clearSecrets() call below to scrub the row at the end.
     */

    await db.migration.update({
      where: { id: migration.id },
      data: { status: "DONE", progress: 100, step: "Completed", finishedAt: new Date() },
    });
    // Security: drop all source credentials now that the job is done.
    await clearSecrets(migration.id, items);

    await notify(
      migration.userId,
      `Migration to ${targetName} completed`,
      `Moved ${paths.length} path(s) and ${databases.length} database(s). Point your DNS at the new server and restart services when ready.`,
      "/dashboard/migrate"
    );
  } catch (e: any) {
    const lastError = `${e?.message ?? e}`.slice(0, 1000);
    console.error(`[migrate] migration ${migration.id} failed:`, e);
    log = appendLog(log, `ERROR: ${lastError}`);
    await db.migration
      .update({
        where: { id: migration.id },
        data: { status: "FAILED", step: "Failed", lastError, log, finishedAt: new Date() },
      })
      .catch(() => {});
    // Security: clear the stored source password/DB secrets even on failure.
    await clearSecrets(migration.id, items).catch(() => {});
    await notify(
      migration.userId,
      `Migration to ${targetName} failed`,
      lastError,
      "/dashboard/migrate"
    );
    // Swallow — the failure is recorded on the Migration row. Re-throwing would
    // make the job loop retry a migration whose secrets we've already cleared.
  }
}

"use client";

import { useEffect, useMemo, useState } from "react";
import { createMigration, getMigration, type MigrationRow } from "@/lib/actions-migrate";
import { StatusDot } from "@/components/ui/primitives";

type ServerOption = { id: string; name: string };
type DbEntry = { engine: "mysql" | "postgres"; name: string; user: string; password: string };

const STEPS = ["Target", "Source", "What to move", "Review"] as const;

function Stepper({ step }: { step: number }) {
  return (
    <div className="mb-6 flex flex-wrap items-center gap-2 text-xs">
      {STEPS.map((s, i) => (
        <div key={s} className="flex items-center gap-2">
          <span
            className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] font-semibold ${
              i === step
                ? "border-brand-400 bg-brand-500/20 text-brand-200"
                : i < step
                  ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300"
                  : "border-white/10 text-slate-500"
            }`}
          >
            {i < step ? "✓" : i + 1}
          </span>
          <span className={i === step ? "text-white" : "text-slate-500"}>{s}</span>
          {i < STEPS.length - 1 && <span className="mx-1 text-slate-700">→</span>}
        </div>
      ))}
    </div>
  );
}

function Row({ k, v }: { k: string; v: React.ReactNode }) {
  return (
    <div className="flex items-start justify-between gap-4">
      <dt className="text-slate-400">{k}</dt>
      <dd className="max-w-[60%] break-words text-right">{v}</dd>
    </div>
  );
}

export function MigrationWizard({ servers }: { servers: ServerOption[] }) {
  const [step, setStep] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [activeId, setActiveId] = useState<string | null>(null);

  // Step 1 — target
  const [serverId, setServerId] = useState(servers[0]?.id ?? "");
  // Step 2 — source
  const [host, setHost] = useState("");
  const [port, setPort] = useState("22");
  const [user, setUser] = useState("root");
  const [password, setPassword] = useState("");
  // Step 3 — what to move
  const [paths, setPaths] = useState<string[]>(["/var/www", "/home"]);
  const [newPath, setNewPath] = useState("");
  const [databases, setDatabases] = useState<DbEntry[]>([]);

  const hostValid = /^[a-zA-Z0-9.\-:[\]]+$/.test(host.trim()) && host.trim().length > 0;
  const portNum = Number(port);
  const portValid = Number.isInteger(portNum) && portNum >= 1 && portNum <= 65535;
  const canContinue = useMemo(() => {
    if (step === 0) return !!serverId;
    if (step === 1) return hostValid && portValid && user.trim().length > 0 && password.length > 0;
    return true;
  }, [step, serverId, hostValid, portValid, user, password]);

  function addPath() {
    const p = newPath.trim();
    if (p && p.startsWith("/") && !paths.includes(p)) {
      setPaths((list) => [...list, p]);
      setNewPath("");
    }
  }
  function addDatabase() {
    setDatabases((list) => [...list, { engine: "mysql", name: "", user: "", password: "" }]);
  }
  function updateDb(i: number, patch: Partial<DbEntry>) {
    setDatabases((list) => list.map((d, idx) => (idx === i ? { ...d, ...patch } : d)));
  }
  function removeDb(i: number) {
    setDatabases((list) => list.filter((_, idx) => idx !== i));
  }

  async function launch() {
    setSubmitting(true);
    setError(null);
    try {
      const res = await createMigration({
        serverId,
        sourceHost: host.trim(),
        sourcePort: portNum,
        sourceUser: user.trim(),
        sourcePassword: password,
        paths,
        databases: databases
          .filter((d) => d.name.trim() && d.user.trim())
          .map((d) => ({ engine: d.engine, name: d.name.trim(), user: d.user.trim(), password: d.password })),
      });
      if (res.error) {
        setError(res.error);
      } else if (res.id) {
        // Drop the plaintext password from client memory the moment it's stored.
        setPassword("");
        setActiveId(res.id);
      }
    } catch {
      setError("Something went wrong starting the migration. Please try again.");
    } finally {
      setSubmitting(false);
    }
  }

  if (activeId) {
    return <MigrationProgress id={activeId} onDone={() => setActiveId(null)} />;
  }

  const serverName = servers.find((s) => s.id === serverId)?.name ?? "—";

  return (
    <div className="card">
      <Stepper step={step} />
      {error && (
        <div className="mb-4 rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">
          {error}
        </div>
      )}

      {step === 0 && (
        <div>
          <h2 className="mb-1 font-semibold">Choose the destination server</h2>
          <p className="mb-4 text-sm text-slate-400">
            Pick the Nxeon server that will receive your files and databases.
          </p>
          {servers.length === 0 ? (
            <p className="text-sm text-slate-400">
              You don&apos;t have any servers yet. Deploy one first, then come back to migrate.
            </p>
          ) : (
            <div className="grid gap-2.5 sm:grid-cols-2">
              {servers.map((s) => (
                <button
                  type="button"
                  key={s.id}
                  onClick={() => setServerId(s.id)}
                  className={`card p-4 text-left transition ${serverId === s.id ? "!border-brand-400 ring-1 ring-brand-400" : "hover:border-white/20"}`}
                >
                  <span className="text-sm font-medium">{s.name}</span>
                </button>
              ))}
            </div>
          )}
        </div>
      )}

      {step === 1 && (
        <div className="space-y-4">
          <div>
            <h2 className="mb-1 font-semibold">Source server SSH details</h2>
            <p className="text-sm text-slate-400">
              The VPS you&apos;re moving away from. We connect over SSH to pull your data — your
              password is encrypted at rest and erased the moment the migration finishes.
            </p>
          </div>
          <div className="grid gap-4 sm:grid-cols-3">
            <div className="sm:col-span-2">
              <label className="label">Source host</label>
              <input
                className="input"
                value={host}
                onChange={(e) => setHost(e.target.value)}
                placeholder="203.0.113.10 or old.example.com"
              />
              {host.length > 0 && !hostValid && (
                <p className="mt-1 text-xs text-red-300">Enter a valid IP address or domain.</p>
              )}
            </div>
            <div>
              <label className="label">SSH port</label>
              <input
                className="input"
                value={port}
                onChange={(e) => setPort(e.target.value.replace(/[^\d]/g, ""))}
                placeholder="22"
              />
              {port.length > 0 && !portValid && (
                <p className="mt-1 text-xs text-red-300">1–65535.</p>
              )}
            </div>
          </div>
          <div className="grid gap-4 sm:grid-cols-2">
            <div>
              <label className="label">SSH username</label>
              <input className="input" value={user} onChange={(e) => setUser(e.target.value)} placeholder="root" />
            </div>
            <div>
              <label className="label">SSH password</label>
              <input
                className="input"
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="••••••••"
                autoComplete="new-password"
              />
            </div>
          </div>
        </div>
      )}

      {step === 2 && (
        <div className="space-y-6">
          <div>
            <h2 className="mb-1 font-semibold">Files to copy</h2>
            <p className="mb-3 text-sm text-slate-400">
              We copy these directories from the source. Defaults cover most web and user data.
            </p>
            <div className="flex flex-wrap gap-2">
              {paths.map((p) => (
                <span
                  key={p}
                  className="inline-flex items-center gap-2 rounded-full border border-white/10 bg-white/[0.05] px-3 py-1 font-mono text-xs"
                >
                  {p}
                  <button
                    type="button"
                    onClick={() => setPaths((list) => list.filter((x) => x !== p))}
                    className="text-slate-500 hover:text-red-300"
                    aria-label={`Remove ${p}`}
                  >
                    ✕
                  </button>
                </span>
              ))}
              {paths.length === 0 && <span className="text-xs text-slate-500">No paths — add one below.</span>}
            </div>
            <div className="mt-3 flex gap-2">
              <input
                className="input font-mono text-xs"
                value={newPath}
                onChange={(e) => setNewPath(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === "Enter") {
                    e.preventDefault();
                    addPath();
                  }
                }}
                placeholder="/etc/nginx"
              />
              <button type="button" className="btn-secondary shrink-0" onClick={addPath}>
                Add path
              </button>
            </div>
          </div>

          <div className="divider" />

          <div>
            <div className="mb-3 flex items-center justify-between">
              <div>
                <h2 className="font-semibold">Databases</h2>
                <p className="text-sm text-slate-400">Optional — add any databases to dump and restore.</p>
              </div>
              <button type="button" className="btn-secondary shrink-0" onClick={addDatabase}>
                Add database
              </button>
            </div>
            <div className="space-y-3">
              {databases.map((d, i) => (
                <div key={i} className="card grid gap-3 !p-3 sm:grid-cols-[120px_1fr_1fr_1fr_auto]">
                  <select
                    className="input"
                    value={d.engine}
                    onChange={(e) => updateDb(i, { engine: e.target.value as DbEntry["engine"] })}
                  >
                    <option value="mysql">MySQL</option>
                    <option value="postgres">PostgreSQL</option>
                  </select>
                  <input className="input" value={d.name} onChange={(e) => updateDb(i, { name: e.target.value })} placeholder="db name" />
                  <input className="input" value={d.user} onChange={(e) => updateDb(i, { user: e.target.value })} placeholder="db user" />
                  <input
                    className="input"
                    type="password"
                    value={d.password}
                    onChange={(e) => updateDb(i, { password: e.target.value })}
                    placeholder="db password"
                    autoComplete="new-password"
                  />
                  <button type="button" className="btn-ghost shrink-0" onClick={() => removeDb(i)} aria-label="Remove database">
                    ✕
                  </button>
                </div>
              ))}
              {databases.length === 0 && (
                <p className="text-xs text-slate-500">No databases added — that&apos;s fine if you only need files.</p>
              )}
            </div>
          </div>
        </div>
      )}

      {step === 3 && (
        <div>
          <h2 className="mb-4 font-semibold">Review &amp; launch</h2>
          <dl className="space-y-2 text-sm">
            <Row k="Destination" v={serverName} />
            <Row k="Source" v={`${user}@${host || "—"}:${port}`} />
            <Row k="Paths" v={paths.length ? paths.join(", ") : "None"} />
            <Row
              k="Databases"
              v={
                databases.filter((d) => d.name.trim()).length
                  ? databases.filter((d) => d.name.trim()).map((d) => `${d.name} (${d.engine})`).join(", ")
                  : "None"
              }
            />
          </dl>
          <p className="mt-4 text-xs text-slate-500">
            Your source SSH and database passwords are encrypted before they&apos;re stored and are
            permanently erased once the migration finishes.
          </p>
        </div>
      )}

      <div className="mt-6 flex items-center justify-between">
        <button
          type="button"
          className="btn-ghost"
          disabled={step === 0 || submitting}
          onClick={() => setStep((s) => Math.max(0, s - 1))}
        >
          ← Back
        </button>
        {step < STEPS.length - 1 ? (
          <button type="button" className="btn-primary" disabled={!canContinue} onClick={() => setStep((s) => s + 1)}>
            Continue →
          </button>
        ) : (
          <button className="btn-primary px-6" disabled={submitting || servers.length === 0} onClick={launch}>
            {submitting ? "Starting…" : "Start migration"}
          </button>
        )}
      </div>
    </div>
  );
}

function MigrationProgress({ id, onDone }: { id: string; onDone: () => void }) {
  const [row, setRow] = useState<MigrationRow | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    let timer: ReturnType<typeof setTimeout>;

    async function poll() {
      try {
        const m = await getMigration(id);
        if (cancelled) return;
        setRow(m);
        if (m && (m.status === "DONE" || m.status === "FAILED")) return; // stop polling
      } catch {
        if (!cancelled) setError("Lost connection while checking progress.");
      }
      if (!cancelled) timer = setTimeout(poll, 3000);
    }
    poll();
    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, [id]);

  const progress = row?.progress ?? 0;
  const done = row?.status === "DONE";
  const failed = row?.status === "FAILED";

  return (
    <div className="space-y-6">
      <div className="card">
        <div className="mb-4 flex items-center justify-between">
          <h2 className="font-semibold">Migration in progress</h2>
          {row && <StatusDot status={row.status} />}
        </div>

        {error && <div className="mb-4 rounded-xl border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-sm text-amber-300">{error}</div>}

        <div className="mb-2 flex items-center justify-between text-sm">
          <span className="text-slate-300">{row?.step ?? "Queued…"}</span>
          <span className="font-semibold">{progress}%</span>
        </div>
        <div className="h-2.5 w-full overflow-hidden rounded-full bg-white/[0.06]">
          <div
            className={`h-full rounded-full transition-all duration-500 ${failed ? "bg-red-400" : done ? "bg-emerald-400" : "bg-brand-500"}`}
            style={{ width: `${progress}%` }}
          />
        </div>

        {failed && row?.lastError && (
          <p className="mt-3 text-sm text-red-300">{row.lastError}</p>
        )}

        {row?.log && (
          <pre className="mt-4 max-h-56 overflow-auto rounded-xl border border-white/10 bg-navy-950/80 p-3 font-mono text-[11px] leading-relaxed text-slate-400">
            {row.log}
          </pre>
        )}
      </div>

      {done && (
        <div className="card border-emerald-500/30">
          <h3 className="mb-1 font-semibold text-emerald-300">Migration complete 🎉</h3>
          <p className="mb-4 text-sm text-slate-400">
            Your files and databases are now on your Nxeon server. A few final steps to go live:
          </p>
          <ul className="space-y-2 text-sm text-slate-300">
            <li className="flex gap-2"><span className="text-emerald-400">1.</span> Point your domain&apos;s DNS at the new server&apos;s IP address.</li>
            <li className="flex gap-2"><span className="text-emerald-400">2.</span> Restart your web server / app services on the new box.</li>
            <li className="flex gap-2"><span className="text-emerald-400">3.</span> Verify the site loads, then decommission the old VPS.</li>
          </ul>
        </div>
      )}

      <div>
        <button type="button" className="btn-secondary" onClick={onDone}>
          ← Start another migration
        </button>
      </div>
    </div>
  );
}

import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { listMigrations } from "@/lib/actions-migrate";
import { PageHeader, StatusDot, timeAgo } from "@/components/ui/primitives";
import { MigrationWizard } from "@/components/customer/MigrationWizard";

export const dynamic = "force-dynamic";

export default async function MigratePage() {
  const user = await requireUser();

  const [servers, migrations] = await Promise.all([
    db.server.findMany({
      where: { userId: user.id },
      orderBy: { createdAt: "desc" },
      select: { id: true, hostname: true, label: true },
    }),
    listMigrations(),
  ]);

  const serverOptions = servers.map((s) => ({ id: s.id, name: s.label || s.hostname }));

  return (
    <div>
      <PageHeader
        title="Migrate to Nxeon"
        sub="Move your files and databases from another VPS provider onto your Nxeon server."
      />

      <MigrationWizard servers={serverOptions} />

      <div className="mt-8">
        <p className="section-label mb-3">Past migrations</p>
        {migrations.length === 0 ? (
          <div className="card py-10 text-center text-sm text-slate-400">
            No migrations yet. Start one above to move your data over.
          </div>
        ) : (
          <div className="card p-0">
            <table className="table-shell">
              <thead>
                <tr>
                  <th>Destination</th>
                  <th>Source</th>
                  <th>Contents</th>
                  <th>Status</th>
                  <th className="text-right">Started</th>
                </tr>
              </thead>
              <tbody>
                {migrations.map((m) => (
                  <tr key={m.id}>
                    <td>{m.serverName ?? "—"}</td>
                    <td className="font-mono text-xs text-slate-400">
                      {m.sourceUser}@{m.sourceHost}:{m.sourcePort}
                    </td>
                    <td className="text-slate-400">
                      {m.paths.length} path{m.paths.length === 1 ? "" : "s"} · {m.databases.length} db
                      {m.databases.length === 1 ? "" : "s"}
                    </td>
                    <td>
                      <StatusDot status={m.status} />
                      {m.status === "RUNNING" && (
                        <span className="ml-2 text-xs text-slate-500">{m.progress}%</span>
                      )}
                    </td>
                    <td className="text-right text-slate-400">{timeAgo(new Date(m.createdAt))}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

